CREATE TABLE IF NOT EXISTS creative_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,version INTEGER NOT NULL,source TEXT NOT NULL DEFAULT 'heuristic_template',status TEXT NOT NULL DEFAULT 'draft',input JSONB NOT NULL,plan JSONB NOT NULL,validation JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_by TEXT,UNIQUE(project_id,version)); CREATE INDEX IF NOT EXISTS creative_plans_project_version_idx ON creative_plans(project_id,version DESC);